//! views are schema-driven via `crate::schema` + `crate::grpc::ReflectionRegistry`.
use crate::chat;
use crate::grpc::{InvokeHandle, MethodKind, ReflectionRegistry, StreamHandle};
use crate::nav::{route_title, Route};
use crate::schema as schema_ui;
use crate::theme::*;
use egui::{Frame, Margin, RichText, Rounding, Stroke};
use schemars::{schema_for, JsonSchema};
use serde::{Deserialize, Serialize};

#[derive(Default)]
pub struct ExplorerState {
    pub service: Option<String>,
    pub method: Option<String>,
    pub request_body: String,
    pub last_response: Option<Result<serde_json::Value, String>>,
    pub last_signature: Option<(String, String)>,
    pub validation: Option<Result<(), String>>,
    pub last_validated: Option<String>,
    pub stream: StreamHandle,
    pub chat_store: crate::chat::store::ChatStore,
    /// Expanded-rows cache: flattens the visible tree into a `Vec<RowHandle>`
    /// per frame so that virtualized `render_array` only resolves schema +
    /// data for rows currently on screen. Rebuilt each frame from the live
    /// payload + collapsing state.
    pub row_cache: Vec<schema_ui::RowHandle>,
}

pub fn render(
    ui: &mut egui::Ui,
    route: Route,
    registry: &ReflectionRegistry,
    explorer: &mut ExplorerState,
    invoke: &InvokeHandle,
    ctx: &egui::Context,
) {
    // Drain any completed invocation result into the explorer state.
    if let Some(res) = invoke.take_result() {
        explorer.last_response = Some(res);
    }

    match route {
        Route::Overview => overview(ui),
        Route::Install => install(ui),
        Route::Chat => chat::view::render_chat(ui, &mut explorer.chat_store, ctx),
        Route::Inspector => inspector(ui),
        Route::State => state_view(ui),
        Route::Grpc => grpc_view(ui, registry),
        Route::GrpcExplorer => grpc_explorer(ui, registry, explorer, invoke, ctx),
        r => stub(ui, route_title(r), description(r)),
    }
}

fn card<R>(ui: &mut egui::Ui, body: impl FnOnce(&mut egui::Ui) -> R) -> R {
    Frame::none()
        .fill(SURFACE)
        .stroke(Stroke::new(1.0, BORDER))
        .rounding(Rounding::same(8.0))
        .inner_margin(Margin::same(16.0))
        .show(ui, body)
        .inner
}

fn stub(ui: &mut egui::Ui, title: &str, desc: &str) {
    ui.label(RichText::new(title).size(22.0).strong().color(FG));
    ui.add_space(4.0);
    ui.label(RichText::new(desc).color(MUTED).size(13.0));
    ui.add_space(16.0);
    card(ui, |ui| {
        ui.label(RichText::new("View not yet ported.").color(FG).size(13.0));
        ui.add_space(4.0);
        ui.label(
            RichText::new(
                "Wire this view to the ZeroClaw core (gRPC/D-Bus) and render real state here.",
            )
            .color(MUTED)
            .size(12.0),
        );
    });
}

fn overview(ui: &mut egui::Ui) {
    ui.label(RichText::new("Overview").size(22.0).strong().color(FG));
    ui.add_space(4.0);
    ui.label(
        RichText::new("Live state of the ZeroClaw control plane.")
            .color(MUTED)
            .size(13.0),
    );
    ui.add_space(16.0);

mod app;
mod auth;
mod catalog;
mod chat;
mod conn;
mod grpc;
mod nav;
mod pagedata;
mod schema; // DEPRECATED: superseded by `catalog::interpret`; remove once views are migrated.
mod theme;
mod views;

use crate::grpc::ReflectionRegistry;

fn main() -> eframe::Result<()> {
    // Background tokio runtime drives the tonic-web reflection client.
    let rt = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");
    let _enter = rt.enter();

    let registry = ReflectionRegistry::new();
    let chat_transport: Option<std::sync::Arc<crate::chat::ChatTransport>> = {
        let endpoint =
            std::env::var("ZEROCLAW_GRPC").unwrap_or_else(|_| "http://127.0.0.1:8090".into());
        let registry = registry.clone();
        let endpoint_clone = endpoint.clone();
        rt.spawn(async move {
            if let Err(e) = grpc::bootstrap(&endpoint_clone, registry).await {
                eprintln!("[zeroclaw] reflection bootstrap failed: {e:#}");
            }
        });

        // Connect the ChatService transport to the same endpoint.
        match rt.block_on(crate::chat::ChatTransport::connect(&endpoint)) {
            Ok(transport) => {
                eprintln!("[zeroclaw] ChatService transport connected to {endpoint}");
                Some(std::sync::Arc::new(transport))
            }
            Err(e) => {
                eprintln!("[zeroclaw] ChatService transport connect failed: {e:#}");
                None
            }
        }
    };

    // Keep runtime alive for the lifetime of the app.
    std::mem::forget(rt);

    let native_options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1280.0, 800.0])
            .with_min_inner_size([960.0, 600.0])
            .with_title("ZeroClaw — Operator Console"),
        ..Default::default()
    };
    eframe::run_native(
        "ZeroClaw",
        native_options,
        Box::new(move |cc| {
            theme::install(&cc.egui_ctx);
            let mut app = app::ZeroClawApp::new_with_registry(cc, registry);
            app.chat_transport = chat_transport;
            Ok(Box::new(app))
        }),
    )
}

//!
//! This is NOT React-style state. There are no notifications, no re-render
//! triggers, no subscribers. The egui frame loop polls `should_repaint()`
//! each frame and the view reads the `Vec<ChatMessage>` directly.
//!
//! `parking_lot::RwLock` is intentionally avoided here: the store is owned
//! by `ExplorerState` which is already behind a single `&mut` in the egui
//! update loop. A plain `Vec` is correct and zero-overhead. If a future
//! background task needs to push messages, wrap the whole `ChatStore` in a
//! `parking_lot::Mutex` at the call site — do not add interior mutability
//! here.

use serde::{Deserialize, Serialize};
use std::time::Instant;
use tokio::sync::mpsc;

use super::transport::ChatFrameEvent;

/// A single chat message part. One logical "turn" may produce several parts
/// (e.g. an assistant reasoning part, then a tool-call part, then a text
/// part). The `kind` discriminator drives the renderer.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChatMessage {
    /// Stable unique id (uuid or nanoid from the server).
    pub id: String,
    /// `"user"` | `"assistant"` | `"tool"` | `"system"`.
    pub role: String,
    /// `"text"` | `"tool-call"` | `"tool-result"` | `"reasoning"`.
    pub kind: String,
    /// Free-form JSON payload — shape depends on `kind`.
    ///
    /// - `text`:      `{ "content": "…" }`
    /// - `tool-call`: `{ "tool": "name", "input": {…}, "tool_call_id": "…" }`
    /// - `tool-result`: `{ "tool_call_id": "…", "output": {…}, "status": "ok"|"error" }`
    /// - `reasoning`: `{ "content": "…", "plan": […] }`
    pub payload: serde_json::Value,
    /// Unix epoch milliseconds.
    pub timestamp: u64,
}

/// Append-only conversation store. Owned by `ExplorerState`.
#[derive(Debug)]
pub struct ChatStore {
    /// All message parts for the current conversation, in arrival order.
    pub messages: Vec<ChatMessage>,
    /// Conversation thread id. Groups episodes. New conversation = new id.
    pub conversation_id: String,
    /// True while we are waiting for the assistant to respond. Drives the
    /// "Thinking…" indicator and disables the submit button.
    pub submitted: bool,
    /// Last time the view requested a repaint. Used by `should_repaint()`
    /// to throttle to ~60fps.
    pub last_repaint: Instant,
    /// Set by the view when the user submits. The app layer picks this up,
    /// calls `ChatTransport::send()`, and stores the receiver in `frame_rx`.
    pub pending_send: Option<super::transport::SendRequestPayload>,
    /// Incoming frame channel from the gRPC stream. Drained by the app
    /// layer each egui frame.
    pub frame_rx: Option<mpsc::Receiver<ChatFrameEvent>>,
    /// Connection status for display.

