        .build_server(false)
        .build_client(true)
        .out_dir(out_dir)
        .compile(&proto_files, &include_dirs)?;

    for f in &proto_files {
        println!("cargo:rerun-if-changed={}", f);
    }
    println!("cargo:rerun-if-changed=build.rs");
    Ok(())
}

