    // The seven originals are still declared.
    for name in [
        "create_snapshot",
        "list_snapshots",
        "get_snapshot",
        "rollback",
        "get_current_state",
        "set_retention",
        "get_stats",
    ] {
        assert!(
            schema.methods.contains_key(name),
            "{name} disappeared from the schema"
        );
    }
}

